// Determine funnel stage and next action for wellness lead
const lead = $input.item.json;
const source = lead.source || 'unknown';
const intent = lead.intent || 'other';
const stage = lead.current_stage || 'new';
const message = (lead.message || '').toLowerCase();

// Wellness-specific intent detection keywords
const bookingKeywords = ['reserver', 'booking', 'cours', 'essayer', 'decouverte', 'horaire', 'schedule', 'dispo', 'place', 'inscription'];
const membershipKeywords = ['abonnement', 'membership', 'membre', 'forfait', 'prix', 'tarif', 'combien', 'mensuel', 'illimite'];
const eventKeywords = ['evenement', 'event', 'brunch', 'soiree', 'retreat', 'atelier', 'workshop'];
const pilatesKeywords = ['pilates', 'reformer', 'mat', 'barre', 'cours', 'debutant', 'avance', 'niveau'];

let detectedIntent = intent;
let funnelStage = stage;
let nextAction = 'nurture';
let offerType = null;

// Detect wellness-specific intents
if (bookingKeywords.some(kw => message.includes(kw))) {
  detectedIntent = 'booking_trial';
  funnelStage = 'trial';
  nextAction = 'offer_trial_class';
  offerType = 'cours_decouverte';
} else if (membershipKeywords.some(kw => message.includes(kw))) {
  detectedIntent = 'membership_inquiry';
  funnelStage = 'conversion';
  nextAction = 'present_membership';
  offerType = 'membership';
} else if (eventKeywords.some(kw => message.includes(kw))) {
  detectedIntent = 'event_interest';
  funnelStage = 'interest';
  nextAction = 'present_events';
  offerType = 'evenement';
} else if (pilatesKeywords.some(kw => message.includes(kw))) {
  detectedIntent = 'pilates_interest';
  funnelStage = 'interest';
  nextAction = 'educate_pilates';
  offerType = 'cours_decouverte';
}

// Stage progression logic
const stageProgression = {
  'new': { next: 'interest', action: 'welcome_and_educate' },
  'interest': { next: 'trial', action: 'offer_trial_class' },
  'trial': { next: 'conversion', action: 'post_trial_followup' },
  'conversion': { next: 'member', action: 'present_membership' },
  'member': { next: 'retention', action: 'engage_and_upsell' },
  'retention': { next: 'advocacy', action: 'referral_program' }
};

return {
  json: {
    ...lead,
    detected_intent: detectedIntent,
    funnel_stage: funnelStage,
    next_action: nextAction,
    offer_type: offerType,
    stage_progression: stageProgression[funnelStage] || stageProgression['new']
  }
};

