const lead = $('Detect Funnel Stage').item.json;
const aiResponse = $input.item.json.message.content;
let response;
try { response = JSON.parse(aiResponse); } catch (e) { response = { reply_text: aiResponse, cta: null }; }

return {
  json: {
    reply_text: response.reply_text,
    action: response.should_book ? 'book' : 'send',
    handoff: false,
    stage: lead.funnel_stage,
    intent: lead.detected_intent,
    source: lead.source,
    conversation_id: lead.conversation_id,
    sender_id: lead.sender_id,
    message_id: lead.message_id,
    offer_type: response.offer_type,
    email_sequence_trigger: response.email_sequence_trigger,
    cta: response.cta
  }
};
